class ParameterCategory(QObject):
    """Repräsentiert eine Parameter-Kategorie"""
    def __init__(self, name, parent=None):
        super().__init__(parent)
        self._name = name
        self._groups = []
        self._parameters = []
    @Property(str, constant=True)
    def name(self):
        return self._name

class ParameterGroup(QObject):
    """Repräsentiert eine Parameter-Gruppe innerhalb einer Kategorie"""
    def __init__(self, name, category, parent=None):
        super().__init__(parent)
        self._name = name
        self._category = category
        self._parameters = []
    @Property(str, constant=True)
    def name(self):
        return self._name

def register_qml_type(engine, file_path, type_name):
    """Registriert einen QML-Typ aus einer Datei"""
    if file_path.exists():
        from PySide6.QtQml import QQmlComponent
        from PySide6.QtCore import QUrl
        url = QUrl.fromLocalFile(str(file_path))
        component = QQmlComponent(engine)
        component.loadUrl(url)
        if not component.isError():
            print(f"QML-Typ '{type_name}' registriert von {file_path.name}")

