def find_python_files(directory):
    """Findet alle .py Dateien in einem Verzeichnis und seinen Unterverzeichnissen"""
    python_files = []
    for root, _, files in os.walk(directory):
        for file in files:
            if file.endswith(".py"):
                python_files.append(os.path.join(root, file))
    return python_files
